package com.staymmate;
import java.util.*;import org.springframework.boot.*;import org.springframework.context.annotation.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.config.annotation.*;
@RestController @RequestMapping("/api") class Api{final Pgs p;final Mates m;final Reviews r;final Leads leads;final Connections connections;final Messages messages;final SmsService sms;Api(Pgs p,Mates m,Reviews r,Leads l,Connections c,Messages msg,SmsService sms){this.p=p;this.m=m;this.r=r;leads=l;connections=c;messages=msg;this.sms=sms;}@GetMapping("/health")Map<String,String> health(){return Map.of("status","ok");}
@GetMapping("/listings")List<Pg> find(@RequestParam(required=false)String location,@RequestParam(required=false)Integer budget,@RequestParam(required=false)Boolean ac,@RequestParam(required=false)Boolean mess,@RequestParam(required=false)Boolean wifi,@RequestParam(required=false)Boolean laundry,@RequestParam(required=false)Boolean parking,@RequestParam(required=false)String type){return p.findAll().stream().filter(x->location==null||location.isBlank()||(x.location+x.city).toLowerCase().contains(location.toLowerCase())).filter(x->budget==null||x.rent<=budget).filter(x->ac==null||x.ac==ac).filter(x->mess==null||x.mess==mess).filter(x->wifi==null||x.wifi==wifi).filter(x->laundry==null||x.laundry==laundry).filter(x->parking==null||x.parking==parking).filter(x->type==null||x.type.isBlank()||x.type.equalsIgnoreCase(type)).sorted(Comparator.comparingDouble((Pg x)->x.rating).reversed()).toList();}@GetMapping("/listings/{id}")Pg one(@PathVariable Long id){return p.findById(id).orElseThrow();}@GetMapping("/listings/{id}/reviews")List<Review> reviewList(@PathVariable Long id){return r.findAll().stream().filter(x->x.pg.id.equals(id)).toList();}@PostMapping("/listings/{id}/reviews")Review review(@PathVariable Long id,@RequestBody Review x){x.id=null;x.pg=one(id);x.stars=Math.max(1,Math.min(5,x.stars));return r.save(x);}@PostMapping("/listings/{id}/contact")ResponseEntity<Map<String,String>> contact(@PathVariable Long id,@RequestBody Lead x){x.id=null;x.pg=one(id);leads.save(x);var result=sms.enabled()?sms.sendOwnerEnquiry(x):new SmsService.SmsResult("SAVED_IN_APP",null);x.smsStatus=result.status();x.smsError=result.error();leads.save(x);String text="QUEUED".equals(result.status())?"Request saved and SMS queued for the owner.":"SAVED_IN_APP".equals(result.status())?"Request saved in the owner dashboard with your phone number.":"Request saved, but SMS was not delivered: "+result.error();return ResponseEntity.status(201).body(Map.of("message",text,"smsStatus",result.status()));}
@GetMapping("/roommates")List<Roommate> mates(){return m.findByActiveTrue();}@PostMapping("/roommates/{id}/connect")ResponseEntity<Map<String,String>> connect(@PathVariable Long id,@RequestBody ConnectionRequest x){x.id=null;x.roommate=m.findById(id).orElseThrow();x.requesterName=x.requesterName==null||x.requesterName.isBlank()?"Staymmate member":x.requesterName;x.message=x.message==null?"I would like to connect and discuss sharing a room.":x.message;connections.save(x);var result=sms.enabled()?sms.sendFriendRequest(x):new SmsService.SmsResult("SAVED_IN_APP",null);x.smsStatus=result.status();x.smsError=result.error();connections.save(x);String text="QUEUED".equals(result.status())?"Friend request saved and SMS queued for "+x.roommate.name+".":"SAVED_IN_APP".equals(result.status())?"Friend request saved with your phone number for "+x.roommate.name+" to review.":"Friend request saved, but SMS was not delivered: "+result.error();return ResponseEntity.status(201).body(Map.of("message",text,"smsStatus",result.status()));}@GetMapping("/owner/enquiries")List<Lead> ownerEnquiries(){return leads.findAll();}@GetMapping("/owner/friend-requests")List<ConnectionRequest> friendRequests(){return connections.findAll();}@PutMapping("/friend-requests/{id}/accept")ConnectionRequest accept(@PathVariable Long id){var c=connections.findById(id).orElseThrow();c.status="ACCEPTED";return connections.save(c);}@GetMapping("/friend-requests/{id}/messages")ResponseEntity<?> conversation(@PathVariable Long id){var c=connections.findById(id).orElseThrow();if(!"ACCEPTED".equals(c.status))return ResponseEntity.status(403).body(Map.of("message","Chat opens only after this friend request is accepted."));return ResponseEntity.ok(messages.findAll().stream().filter(x->x.connection.id.equals(id)).toList());}@PostMapping("/friend-requests/{id}/messages")ResponseEntity<?> sendMessage(@PathVariable Long id,@RequestBody DirectMessage msg){var c=connections.findById(id).orElseThrow();if(!"ACCEPTED".equals(c.status))return ResponseEntity.status(403).body(Map.of("message","Chat opens only after this friend request is accepted."));msg.id=null;msg.connection=c;return ResponseEntity.status(201).body(messages.save(msg));}@GetMapping("/profiles/{email}")ResponseEntity<Roommate> profile(@PathVariable String email){return m.findByActiveTrue().stream().filter(x->email.equalsIgnoreCase(x.email)).findFirst().map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}@PutMapping("/profiles/{email}")Roommate save(@PathVariable String email,@RequestBody Roommate x){x.id=m.findByActiveTrue().stream().filter(y->email.equalsIgnoreCase(y.email)).map(y->y.id).findFirst().orElse(null);x.email=email;if(x.avatar==null||x.avatar.isBlank())x.avatar=x.gender!=null&&x.gender.equalsIgnoreCase("Female")?"https://randomuser.me/api/portraits/women/44.jpg":"https://randomuser.me/api/portraits/men/44.jpg";return m.save(x);}
@PostMapping("/chat")Map<String,String> chat(@RequestBody Map<String,String> q){String s=q.getOrDefault("message","").toLowerCase(),a;if(s.contains("deposit")||s.contains("balance")||s.contains("advance")||s.contains("refund"))a="The booking deposit is an advance paid to reserve a bed. Confirm whether it is refundable, the notice period, and what deductions apply. Never transfer money before visiting or receiving a signed receipt.";else if(s.contains("rent")||s.contains("cost")||s.contains("price"))a="Monthly rent depends on location, sharing and facilities. Use the budget filter, then compare rent and deposit on each card. Ask the owner whether electricity, meals and maintenance are included.";else if(s.contains("review")||s.contains("rating"))a="Ratings help you compare listings, but visit before deciding. Check recent reviews for cleanliness, food, water supply, security and whether the room photo matches the actual room.";else if(s.contains("roommate")||s.contains("habit")||s.contains("sleep")||s.contains("food"))a="Select a PG first. Staymmate then takes you directly to roommate suggestions in that location. Compare routines, sleep timing, food preferences, budget and habits before sending a request.";else if(s.matches(".*(ac|wifi|laundry|parking|mess).*"))a="Use the facility filters. Also ask the owner if AC electricity is charged separately, how many meals mess includes, and whether Wi-Fi and laundry have limits.";else if(s.contains("safe")||s.contains("security")||s.contains("scam"))a="For safety, visit in daytime, speak to current residents, verify the owner or manager, check CCTV and entry rules, and pay only to a verified account after getting a receipt.";else if(s.contains("book")||s.contains("owner")||s.contains("contact")||s.contains("visit"))a="Choose a PG, select it to view local roommate matches, then use Contact owner to request a visit. During the visit, check the room, washroom, food, electricity charges and refund policy.";else if(s.contains("hello")||s.contains("hi"))a="Hello. I am Staymmate support. I can help you compare PG rent, deposits, facilities, safety, owner visits, reviews and roommate compatibility.";else a="I can help with a PG search, budget, rent, deposits, AC, mess, safety, reviews, owner visits and roommate matches. Please ask a specific question so I can guide you.";return Map.of("answer",a);}}
@Configuration class Web implements WebMvcConfigurer{public void addCorsMappings(CorsRegistry x){x.addMapping("/api/**").allowedOrigins("http://localhost:5173").allowedMethods("*");}@Bean CommandLineRunner seed(Pgs p,Mates m){return a->{if(p.count()>0)return;String[] names={"Cozy Nest Residency","Harbour View Homes","Campus Comfort","Western Heights PG","Deccan House","Metro Living","Marine Residency","Powai Lake View","Thane Green Homes","Navi Mumbai Hub","Nashik Student Stay","Nagpur Central Rooms","Kolhapur Comfort"};String[] locations={"Andheri","Bandra","Wadala","Borivali","Pune","Kandivali","Churchgate","Powai","Thane","Navi Mumbai","Nashik","Nagpur","Kolhapur"};for(int i=0;i<names.length;i++)p.save(pg(names[i],locations[i],7000+i*950,12000+i*1500,i%2==0,i%3!=0,i%4!=0,i%3==0,i%2!=0,4.0+(i%5)*.15,"Verified PG with safe entry, housekeeping and flexible sharing."));m.save(mate("Aarav Shah","aarav@example.com","Andheri","Male",24,16000,"9am-6pm office","11pm-7am","Vegetarian","None","Product designer who values a tidy, calm home."));m.save(mate("Isha Kulkarni","isha@example.com","Bandra","Female",22,19000,"College 10am-4pm","12am-8am","Eggetarian","Occasional music","Architecture student and weekend explorer."));m.save(mate("Rohan Patil","rohan@example.com","Wadala","Male",26,13000,"Rotating shifts","1am-9am","Non-vegetarian","Smokes outside","Healthcare professional, friendly and punctual."));};}Pg pg(String n,String l,int rent,int dep,boolean ac,boolean mess,boolean wifi,boolean laundry,boolean parking,double rating,String d){Pg x=new Pg();x.name=n;x.location=l;x.city=l;x.rent=rent;x.deposit=dep;x.ac=ac;x.mess=mess;x.wifi=wifi;x.laundry=laundry;x.parking=parking;x.type="Private";x.rating=rating;x.image="https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=1200&q=80";x.description=d;x.amenities="Wi-Fi, CCTV, housekeeping, power backup";x.owner="Verified owner";x.phone="+91 98XXXXXX10";return x;}Roommate mate(String n,String e,String l,String g,int age,int b,String sch,String sl,String food,String habits,String bio){Roommate x=new Roommate();x.name=n;x.email=e;x.location=l;x.gender=g;x.age=age;x.budget=b;x.schedule=sch;x.sleep=sl;x.food=food;x.habits=habits;x.bio=bio;x.avatar="https://i.pravatar.cc/150?u="+e;return x;}}
